&lt;p&gt;यहाँ अनुसरित तर्क है:&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;तर्क:&lt;/strong&gt; पहली संख्या &amp;times; 2 + दूसरी &lt;span style=&quot;&quot;&gt;संख्या&lt;/span&gt; - (&lt;span style=&quot;&quot;&gt;दूसरी&lt;/span&gt; &lt;span style=&quot;&quot;&gt;संख्या&lt;/span&gt;&amp;nbsp;&amp;divide; 2) = तीसरी &lt;span style=&quot;&quot;&gt;संख्या&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;5 + 8 = 14&amp;nbsp;&amp;rarr; 5&amp;nbsp;&lt;/span&gt;&amp;times;&amp;nbsp;2 + 8 - (8&amp;nbsp;&amp;divide;&amp;nbsp;2) = 10 + 8 - 4 = 18 - 4 = 14&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;9 + 6 = 21&amp;nbsp;&amp;rarr; 9&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;times;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;2 + 6&amp;nbsp;- (6&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;divide;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;2) = 18&amp;nbsp;+ 6&amp;nbsp;- 3&amp;nbsp;= 24&amp;nbsp;- 3&amp;nbsp;= 21&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;4 + 10 = 13&amp;nbsp;&amp;rarr; 4&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;times;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;2 + 10&amp;nbsp;- (10&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;divide;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;2) = 8&amp;nbsp;+ 10&amp;nbsp;- 5&amp;nbsp;= 18 - 5&amp;nbsp;= 13&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;इसी प्रकार,&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;7 + 2 = ?&amp;nbsp;&amp;rarr; 7&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;times;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;2 + 2&amp;nbsp;- (2&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;divide;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;2) = 14&amp;nbsp;+ 2&amp;nbsp;- 1&amp;nbsp;= 16&amp;nbsp;- 1&amp;nbsp;= 15&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;अत:, &lt;strong&gt;&amp;#39;15&amp;#39;&lt;/strong&gt; सही उत्तर है।&lt;/p&gt;

